/* ---------- experiment statistics ---------- */
function wsNormalCdf(x){var t=1/(1+.2316419*Math.abs(x)),d=.3989423*Math.exp(-x*x/2),p=d*t*(.3193815+t*(-.3565638+t*(1.781478+t*(-1.821256+t*1.330274))));return x>0?1-p:p}
function workspaceExperimentStats(item){
  var baseline=wsNum(item.baselineRate),mde=wsNum(item.mde),target=wsNum(item.confidenceTarget)||95,n1=wsNum(item.controlVisitors),c1=wsNum(item.controlConversions),n2=wsNum(item.variantVisitors),c2=wsNum(item.variantConversions),zAlpha=target>=99?2.576:target>=95?1.96:1.645,required=null;
  if(baseline>0&&baseline<100&&mde>0){var p1=baseline/100,p2=Math.min(.999,p1*(1+mde/100)),delta=Math.abs(p2-p1),pbar=(p1+p2)/2;required=delta?Math.ceil(2*Math.pow(zAlpha+.84,2)*pbar*(1-pbar)/(delta*delta)):null}
  if(!(n1>0)||!(n2>0)||c1==null||c2==null||c1>n1||c2>n2)return {required:required,confidence:null,verdict:'Waiting for results'};
  var r1=c1/n1,r2=c2/n2,pooled=(c1+c2)/(n1+n2),se=Math.sqrt(pooled*(1-pooled)*(1/n1+1/n2)),z=se?(r2-r1)/se:0,pvalue=2*(1-wsNormalCdf(Math.abs(z))),confidence=Math.max(0,Math.min(100,(1-pvalue)*100)),lift=r1?(r2-r1)/r1*100:null,cleared=confidence>=target&&(!required||n1>=required&&n2>=required),verdict=!cleared?'Directional':r2>r1?'Variant wins':r2<r1?'Control wins':'No difference';return {required:required,confidence:confidence,controlRate:r1*100,variantRate:r2*100,lift:lift,verdict:verdict,cleared:cleared};
}
function renderExperimentStatsPreview(){if(!$('xt-stats-preview'))return;var item=typeof xtReadForm==='function'?xtReadForm():{},s=workspaceExperimentStats(item),state=s.cleared?'good':s.confidence==null?'':'warn';$('xt-stats-preview').className='quality-banner '+state;$('xt-stats-preview').innerHTML='<div class="quality-icon"><i class="bi bi-beaker"></i></div><div><strong>'+wsEsc(s.verdict)+'</strong><small>'+(s.confidence==null?'Required sample '+(s.required==null?'needs baseline and MDE':s.required.toLocaleString()+' per arm'):'Control '+wsPct(s.controlRate,2)+' · variant '+wsPct(s.variantRate,2)+' · lift '+wsPct(s.lift,1)+' · required '+(s.required==null?'not estimated':s.required.toLocaleString()+' per arm'))+'</small></div><div class="quality-score">'+(s.confidence==null?'—':s.confidence.toFixed(1)+'%')+'</div>'}

/* ---------- creative learning aggregation ---------- */
function renderCreativeLearning(){
  if(!$('gl-learn-rows'))return;var dimension=wsValue('gl-learn-dimension')||'concept',minimum=+wsValue('gl-learn-min-spend')||0,groups={};creativeAssets.forEach((asset)=> {var key=String(asset[dimension]||'Unclassified').trim()||'Unclassified';if(!groups[key])groups[key]=[];groups[key].push(asset)});var rows=Object.keys(groups).map((key)=> {var assets=groups[key],spend=0,orders=0,revenue=0,graduates=0;assets.forEach((asset)=> {var m=creativeMetrics(asset);spend+=wsZero(asset.spend);orders+=wsZero(m.orders);revenue+=wsZero(asset.revenue);if(creativeVerdict(asset).label==='Graduate')graduates++});return {key:key,assets:assets.length,spend:spend,orders:orders,revenue:revenue,cpa:orders?spend/orders:null,roas:spend?revenue/spend:null,graduates:graduates}}).filter((x)=> x.spend>=minimum).sort((a,b)=> b.spend-a.spend);
  var best=rows.filter((x)=> x.orders>0).sort((a,b)=> (b.roas||0)-(a.roas||0))[0],most=rows[0],winner=rows.slice().sort((a,b)=> b.graduates-a.graduates)[0];$('gl-learn-summary').innerHTML='<div class="learn-card"><span>Variables read</span><b>'+rows.length+'</b></div><div class="learn-card"><span>Most spend</span><b>'+(most?wsEsc(most.key):'—')+'</b></div><div class="learn-card"><span>Best ROAS</span><b>'+(best?wsEsc(best.key)+' · '+best.roas.toFixed(2):'—')+'</b></div><div class="learn-card"><span>Most graduates</span><b>'+(winner&&winner.graduates?wsEsc(winner.key)+' · '+winner.graduates:'—')+'</b></div><div class="learn-card"><span>Total evidence</span><b>'+wsMoney(rows.reduce((n,x)=> n+x.spend,0))+'</b></div>';
  $('gl-learn-rows').innerHTML=rows.length?rows.map((x)=> {var learning=x.graduates?'Validated in '+x.graduates+' graduating asset'+(x.graduates===1?'':'s')+'.':x.orders?'Commercial signal exists but no asset has graduated.':'No commercial conversion signal yet.';return '<tr><td><span class="row-title">'+wsEsc(x.key)+'</span></td><td class="num">'+x.assets+'</td><td class="num">'+wsMoney(x.spend)+'</td><td class="num">'+x.orders+'</td><td class="num">'+wsMoney(x.revenue)+'</td><td class="num">'+wsMoney(x.cpa)+'</td><td class="num">'+(x.roas==null?'—':x.roas.toFixed(2))+'</td><td class="num">'+x.graduates+'</td><td>'+wsEsc(learning)+'</td></tr>'}).join(''):wsEmpty(9,'No aggregated evidence','Add creative performance or lower the minimum-spend filter.')
}

function renderProductionAll(){
  if(typeof dailyRecords==='undefined')return;workspaceNormalizeDaily();renderProductionHome();renderWorkspace();renderTrends();renderForecastPreview();renderForecastArchive();renderAudiences();renderMeasurementHealth();renderCompliance();renderAuditArchive();renderCreativeLearning();renderExperimentStatsPreview();
}

/* ---------- production event bindings ---------- */
function bindProduction(){
  $('workspace-tabs').addEventListener('click',function(e){var b=e.target.closest('[data-prod-pane]');if(!b)return;this.querySelectorAll('button').forEach((x)=> {x.classList.toggle('on',x===b)});document.querySelectorAll('[id^="workspace-pane-"]').forEach((x)=> {x.classList.toggle('on',x.id==='workspace-pane-'+b.dataset.prodPane)})});
  $('compliance-tabs').addEventListener('click',function(e){var b=e.target.closest('[data-comp-pane]');if(!b)return;this.querySelectorAll('button').forEach((x)=> {x.classList.toggle('on',x===b)});document.querySelectorAll('[id^="compliance-pane-"]').forEach((x)=> {x.classList.toggle('on',x.id==='compliance-pane-'+b.dataset.compPane)})});
  $('ws-account-save').addEventListener('click',saveAccount);$('ws-account-cancel').addEventListener('click',()=> {wsFormReset('account')});$('ws-product-save').addEventListener('click',saveProduct);$('ws-product-cancel').addEventListener('click',()=> {wsFormReset('product')});$('ws-campaign-save').addEventListener('click',saveCampaign);$('ws-campaign-cancel').addEventListener('click',()=> {wsFormReset('campaign')});$('ws-target-save').addEventListener('click',saveTarget);$('ws-target-cancel').addEventListener('click',()=> {wsFormReset('target')});$('ws-target-scope').addEventListener('change',()=> {renderScopeOptions('target')});$('ws-rule-scope').addEventListener('change',()=> {renderScopeOptions('rule')});$('ws-rule-save').addEventListener('click',saveRule);$('ws-rule-reset').addEventListener('click',()=> {if(confirm('Remove all custom rule overrides? Built-in workspace defaults will remain.')){workspaceState.rules=[];workspaceAudit('Workspace','Decision rules reset','All overrides removed');renderRules();renderAll();renderProductionAll()}});$('ws-setting-save').addEventListener('click',saveSettings);$('ws-save-now').addEventListener('click',()=> {TWC.store.saveNow('manual checkpoint').then(()=> {toast('Workspace checkpoint saved')})});$('ws-import-daily').addEventListener('click',()=> {setActive('daily');$('dp-file').click()});
  $('v-workspace').addEventListener('click',(e)=> {var edit=e.target.closest('[data-ws-edit]'),archive=e.target.closest('[data-ws-archive]'),remove=e.target.closest('[data-rule-remove]'),restore=e.target.closest('[data-backup-restore]'),removeBackup=e.target.closest('[data-backup-remove]');if(edit)editEntity(edit.dataset.wsEdit,edit.dataset.id);if(archive)archiveEntity(archive.dataset.wsArchive,archive.dataset.id);if(remove){workspaceState.rules=workspaceState.rules.filter((x)=> x.id!==remove.dataset.ruleRemove);workspaceAudit('Workspace','Decision-rule override removed','Override '+remove.dataset.ruleRemove);renderRules()}if(restore&&confirm('Restore this checkpoint? A new checkpoint of the restored state will be created.')){TWC.store.restoreBackup(restore.dataset.backupRestore).then((ok)=> {if(ok){renderBackups();toast('Checkpoint restored')}})}if(removeBackup&&confirm('Remove this recovery checkpoint?')){TWC.store.removeBackup(removeBackup.dataset.backupRemove).then(renderBackups)}});
  ['trend-range','trend-account','trend-product'].forEach((id)=> {$(id).addEventListener('change',renderTrends)});['fc2-current-spend','fc2-current-orders','fc2-current-revenue','fc2-proposed-spend','fc2-elastic-low','fc2-elastic-base','fc2-elastic-high','fc2-horizon','fc2-margin','fc2-inventory','fc2-cash'].forEach((id)=> {$(id).addEventListener('input',renderForecastPreview)});$('fc2-start').value=wsToday();$('fc2-use-latest').addEventListener('click',fc2UseLatest);$('fc2-save').addEventListener('click',fc2Save);$('fc2-rows').addEventListener('click',(e)=> {var c=e.target.closest('[data-fc2-calibrate]'),r=e.target.closest('[data-fc2-remove]');if(c)fc2Calibrate(c.dataset.fc2Calibrate);if(r){var item=wsFind('forecastScenarios',r.dataset.fc2Remove);if(item){item.archived=true;workspaceState.forecastScenarios=workspaceState.forecastScenarios.filter((x)=> x.id!==item.id);workspaceAudit('Decision','Forecast archived',item.name,item.id);renderForecastArchive()}}});
  $('ar-save').addEventListener('click',audienceSave);$('ar-cancel').addEventListener('click',audienceReset);$('ar-search').addEventListener('input',renderAudiences);$('ar-filter').addEventListener('change',renderAudiences);$('ar-cards').addEventListener('click',(e)=> {var edit=e.target.closest('[data-ar-edit]'),refresh=e.target.closest('[data-ar-refresh]'),archive=e.target.closest('[data-ar-archive]');if(edit)audienceEdit(edit.dataset.arEdit);if(refresh){var x=wsFind('audiences',refresh.dataset.arRefresh);if(x){x.refreshed=wsToday();x.nextRefresh=wsShift(wsToday(),30);workspaceAudit('Governance','Audience refreshed',x.name,x.id);renderAudiences()}}if(archive){var a=wsFind('audiences',archive.dataset.arArchive);if(a){a.status=a.status==='Archived'?'Active':'Archived';workspaceAudit('Governance','Audience '+a.status.toLowerCase(),a.name,a.id);renderAudiences()}}});
  $('mh-save').addEventListener('click',measurementSave);$('mh-cancel').addEventListener('click',measurementReset);$('mh-search').addEventListener('input',renderMeasurementHealth);$('mh-filter').addEventListener('change',renderMeasurementHealth);$('mh-cards').addEventListener('click',(e)=> {var edit=e.target.closest('[data-mh-edit]'),recheck=e.target.closest('[data-mh-recheck]'),archive=e.target.closest('[data-mh-archive]');if(edit)measurementEdit(edit.dataset.mhEdit);if(recheck){var x=wsFind('measurementChecks',recheck.dataset.mhRecheck);if(x){measurementReset();wsSet('mh-source',x.source);wsSet('mh-event',x.event);wsSet('mh-browser',x.browser);wsSet('mh-server',x.server);wsSet('mh-backend',x.backend);wsSet('mh-dedupe',x.dedupe);wsSet('mh-emq',x.emq);wsSet('mh-diagnostics','Recheck of '+x.id+': ');$('mh-diagnostics').focus()}}if(archive){var y=wsFind('measurementChecks',archive.dataset.mhArchive);if(y){workspaceState.measurementChecks=workspaceState.measurementChecks.filter((z)=> z.id!==y.id);workspaceAudit('Governance','Measurement check archived',y.source+' · '+y.event,y.id);renderMeasurementHealth()}}});
  $('clm-save').addEventListener('click',claimSave);$('clm-cancel').addEventListener('click',claimReset);$('clm-search').addEventListener('input',renderCompliance);$('clm-filter').addEventListener('change',renderCompliance);$('inc-save').addEventListener('click',incidentSave);$('inc-cancel').addEventListener('click',incidentReset);$('inc-filter').addEventListener('change',renderCompliance);$('clm-cards').addEventListener('click',(e)=> {var edit=e.target.closest('[data-clm-edit]'),version=e.target.closest('[data-clm-version]'),retire=e.target.closest('[data-clm-retire]');if(edit)claimEdit(edit.dataset.clmEdit);if(version){var x=wsFind('complianceClaims',version.dataset.clmVersion);if(x){claimEdit(x.id);workspaceEditing.claim='';wsSet('clm-version',String((Number.parseFloat(x.version)||1)+.1).replace(/0+$/,''));wsSet('clm-approved',wsToday());wsSet('clm-expires',wsShift(wsToday(),90));$('clm-save').textContent='Save new version'}}if(retire){var y=wsFind('complianceClaims',retire.dataset.clmRetire);if(y){y.status='Retired';workspaceAudit('Governance','Claim retired',y.claimId+' v'+y.version,y.id);renderCompliance()}}});$('inc-cards').addEventListener('click',(e)=> {var edit=e.target.closest('[data-inc-edit]'),resolve=e.target.closest('[data-inc-resolve]'),archive=e.target.closest('[data-inc-archive]');if(edit)incidentEdit(edit.dataset.incEdit);if(resolve){var x=wsFind('complianceIncidents',resolve.dataset.incResolve);if(x){x.status='Resolved';workspaceAudit('Governance','Policy incident resolved',x.scope,x.id);renderCompliance()}}if(archive){var y=wsFind('complianceIncidents',archive.dataset.incArchive);if(y){workspaceState.complianceIncidents=workspaceState.complianceIncidents.filter((z)=> z.id!==y.id);workspaceAudit('Governance','Policy incident archived',y.scope,y.id);renderCompliance()}}});
  $('aa-save-report').addEventListener('click',archiveWeeklyReport);$('aa-filter').addEventListener('change',renderAuditArchive);$('aa-report-list').addEventListener('click',(e)=> {var exp=e.target.closest('[data-report-export]'),open=e.target.closest('[data-report-open]');if(exp)exportArchivedReport(exp.dataset.reportExport);if(open)openArchivedReport(open.dataset.reportOpen)});
  $('import-review-close').addEventListener('click',()=> {$('import-review-dialog').close()});$('import-review-cancel').addEventListener('click',()=> {workspacePendingImport=null;$('import-review-dialog').close()});$('import-review-commit').addEventListener('click',workspaceCommitImport);
  ['xt-baseline-rate','xt-mde','xt-confidence-target','xt-control-visitors','xt-control-conversions','xt-variant-visitors','xt-variant-conversions'].forEach((id)=> {$(id).addEventListener('input',renderExperimentStatsPreview);$(id).addEventListener('change',renderExperimentStatsPreview)});$('gl-learn-dimension').addEventListener('change',renderCreativeLearning);$('gl-learn-min-spend').addEventListener('change',renderCreativeLearning);
  wsFormReset('account');wsFormReset('product');wsFormReset('campaign');wsFormReset('target');audienceReset();measurementReset();claimReset();incidentReset();
}
bindProduction();

